import type { Metadata } from "next";
import { db } from "@/lib/db";
import { UseCaseLanding, type UseCaseContent } from "@/components/marketing/UseCaseLanding";
import { cheapestVpsPricing } from "@/lib/marketing/cheapest-vps";

export const dynamic = "force-dynamic";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export async function generateMetadata(): Promise<Metadata> {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  const from = pricing?.fromLabel ?? "$6.49";

  return {
    title: "n8n Hosting — Self-Hosted n8n VPS, One-Click, Full Root",
    description:
      `Self-host n8n on a fast NVMe VPS with a one-click install, full root, unlimited workflows, dedicated IPv4, daily backups, and DDoS protection. From ${from}/mo.`,
    alternates: { canonical: "/n8n-hosting" },
    openGraph: {
      type: "article",
      title: "n8n Hosting — Self-Hosted n8n VPS, One-Click, Full Root",
      description:
        "Own your automation: one-click n8n on an NVMe VPS with full root, dedicated IP, backups and DDoS protection. Unlimited workflows, your data.",
      url: `${APP_URL}/n8n-hosting`,
    },
  };
}

function buildContent(pricing: ReturnType<typeof cheapestVpsPricing>): UseCaseContent {
  const fromLabel = pricing?.fromLabel ?? "$6.49";
  const renewsLabel = pricing?.renewsLabel ?? null;
  const renewalNote = renewsLabel ? `, then renews at ${renewsLabel}/mo` : "";

  return {
    eyebrow: "n8n hosting",
    title: "Self-host n8n on a",
    highlight: "real VPS",
    sub: `Run your own n8n automation server with a one-click install, full root, and no per-execution fees. Unlimited workflows on a dedicated NVMe box, from ${fromLabel}/mo for your first term${renewalNote}.`,
    intro: [
      "n8n is at its best when you own it: no execution limits, no per-workflow pricing, and your data never leaves your server. Self-hosting it on a VPS gives you a dedicated machine with its own IP — the right home for workflows that touch private APIs, internal databases, and credentials you'd rather not hand to a SaaS.",
      "Nxeon deploys n8n for you in one click, running and reachable on first boot, so you skip the Node, database, and reverse-proxy setup and go straight to building automations. Everything runs on enterprise NVMe over a self-healing ZFS mirror, so busy schedules and webhook bursts stay responsive.",
      "Because you have full root, you can put n8n behind your own domain and SSL, pin it to a version you trust, connect it to a Postgres database for durable execution history, and snapshot before every upgrade. It's your automation hub, on infrastructure you control.",
    ],
    whyTitle: "Built for n8n",
    why: [
      { title: "One-click n8n install", body: "Choose the n8n image and your server boots with n8n installed and running — no Node, database, or proxy wrangling before your first workflow." },
      { title: "No execution limits", body: "Self-hosted means no per-execution billing and no workflow caps. Run as many automations and steps as your server can handle." },
      { title: "Your data stays yours", body: "Credentials, payloads, and execution history live on your own VPS behind your firewall — not in someone else's multi-tenant cloud." },
      { title: "Full root + dedicated IP", body: "SSH in to add a domain and SSL, set environment variables, or wire n8n to a Postgres database. A dedicated IPv4 makes webhooks and allow-lists reliable." },
      { title: "Snapshots before upgrades", body: "Take an instant snapshot before bumping n8n to a new version — if a node changes behaviour, roll back in seconds." },
      { title: "DDoS protection + backups", body: "Always-on DDoS mitigation, a managed firewall, and automatic daily backups keep your automation server online and recoverable." },
    ],
    steps: [
      { title: "Create your account", body: "Sign up with no credit card required and open the deploy wizard." },
      { title: "Pick n8n + a plan", body: "Select the one-click n8n image and a plan (Starter is plenty to begin), then deploy — n8n is live in under a minute." },
      { title: "Add a domain + SSL", body: "Point a domain at your dedicated IP and issue SSL so your editor and webhook URLs run over HTTPS." },
      { title: "Build your first workflow", body: "Open the n8n editor, connect your apps and credentials, and start automating. Full root is there whenever you want to tune it." },
    ],
    specNote:
      "n8n runs comfortably on a 2 GB Starter for personal and small-team automation. Move up to Standard (4 GB) if you run many concurrent workflows, heavy data transforms, or a bundled Postgres database — and resize any time without a rebuild.",
    faq: [
      { q: "Is n8n really one-click here?", a: "Yes. Pick the one-click n8n image and your VPS boots with n8n installed and running. Point a domain at it, add SSL, and you're building workflows — no manual Node or database setup." },
      { q: "Do I pay per execution or per workflow?", a: "No. This is self-hosted n8n on your own VPS, so there are no per-execution fees and no workflow limits. You pay a flat monthly price for the server and run as much as it can handle." },
      { q: "Which plan should I start with?", a: "A 2 GB Starter is fine for personal and small-team automation. Choose Standard (4 GB) for many concurrent workflows, heavy data transforms, or a bundled Postgres database. You can resize any time — no rebuild." },
      { q: "Can I use my own domain and keep it private?", a: "Yes. With full root and a dedicated IPv4 you can put n8n behind your own domain and SSL, restrict access with the managed firewall, and keep all credentials and data on your server." },
      { q: "How do I upgrade n8n safely?", a: "Take an instant snapshot first, then upgrade from the shell. If a new version changes a node's behaviour, roll back to the snapshot in seconds. Automatic daily backups add another safety net." },
    ],
    related: [
      { label: "VPS hosting", href: "/vps" },
      { label: "Docker hosting", href: "/docker-hosting" },
      { label: "Node.js hosting", href: "/nodejs-hosting" },
      { label: "Pricing", href: "/pricing" },
      { label: "Free tools", href: "/tools" },
    ],
  };
}

export default async function N8nHostingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  return <UseCaseLanding content={buildContent(pricing)} plans={plans} />;
}
