function buildContent(pricing: ReturnType<typeof cheapestVpsPricing>): UseCaseContent {
  const fromLabel = pricing?.fromLabel ?? "$6.49";
  const renewsLabel = pricing?.renewsLabel ?? null;
  const renewalNote = renewsLabel ? `, then renews at ${renewsLabel}/mo` : "";

  return {
    eyebrow: "WordPress hosting",
    title: "WordPress hosting on a",
    highlight: "real VPS",
    sub: `Your own NVMe server with full root access — not a cramped shared plan. One-click WordPress, free SSL, daily backups, and DDoS protection, from ${fromLabel}/mo for your first term${renewalNote}.`,
    intro: [
      "Shared WordPress hosting throttles you the moment traffic picks up: no root, noisy neighbours, and hard limits on plugins, PHP workers, and cron. A VPS gives you the whole machine — dedicated CPU and NVMe, your own IP, and full control over PHP, the web server, and caching.",
      "Nxeon deploys WordPress for you in one click on Ubuntu or Debian, fully configured on first boot, so you skip the LEMP/LAMP setup and go straight to building. Everything runs on enterprise NVMe over a self-healing ZFS mirror, so page loads and database queries stay fast under load.",
    ],
    whyTitle: "Built for WordPress",
    why: [
      { title: "One-click install", body: "Choose the WordPress image and your server boots with the web server, PHP, and database already configured — no manual stack setup." },
      { title: "NVMe on ZFS", body: "Enterprise NVMe SSD on a mirrored, self-healing ZFS pool. Fast reads for cached pages and snappy database queries even during traffic spikes." },
      { title: "Full root access", body: "SSH in and run anything — install caching (Redis, Varnish), tune PHP-FPM, add WP-CLI, or self-host a staging copy. It's your machine." },
      { title: "Free SSL + dedicated IP", body: "One-click Let's Encrypt certificates for your domain, and a dedicated IPv4 so your site isn't sharing a reputation with anyone else." },
      { title: "Daily backups + snapshots", body: "Automatic backups plus instant snapshots before you update a plugin or theme — roll back in seconds if something breaks." },
      { title: "DDoS protection", body: "Always-on network DDoS mitigation and a managed firewall keep your site online when it gets attention (wanted or not)." },
    ],
    steps: [
      { title: "Create your account", body: "Sign up with no credit card required and open the deploy wizard." },
      { title: "Pick WordPress + a plan", body: "Select the one-click WordPress image and a plan that fits your traffic, then deploy — it's live in under a minute." },
      { title: "Point your domain + get SSL", body: "Add your domain, aim its DNS at your server's IP, and issue a free SSL certificate with one click." },
      { title: "Log in and build", body: "Open wp-admin, install your theme and plugins, and you're publishing. Full root is there whenever you need to tune it." },
    ],
    specNote:
      "A 2 GB Starter runs a personal or small business WordPress site comfortably. Pick Standard (4 GB) for a busy blog, membership site, or WooCommerce store — and resize any time without a rebuild.",
    faq: [
      { q: "Is this managed WordPress hosting?", a: "It's a self-managed VPS with a one-click WordPress install: we provision WordPress fully configured on first boot, and you manage the site from wp-admin. You get full root if you ever want to tune the stack, but you don't have to." },
      { q: "Which plan do I need for WordPress?", a: "A 2 GB Starter is plenty for a personal or small business site. Choose Standard (4 GB) or Pro (8 GB) for higher traffic, WooCommerce, or heavy plugins. You can resize vCPU, RAM, and disk any time — no rebuild." },
      { q: "Can I host multiple WordPress sites on one VPS?", a: "Yes. With full root you can run several sites (and databases) on a single server using virtual hosts — a cost-effective way to manage a small portfolio of sites." },
      { q: "Do I get free SSL and backups?", a: "Yes. Every plan includes one-click Let's Encrypt SSL, automatic daily backups, and instant snapshots. DDoS protection and a dedicated IPv4 are included too." },
      { q: "Can I migrate my existing WordPress site?", a: "Absolutely — with full root and SFTP you can move your files and database over, or use a standard WordPress migration plugin. Our free tools can help you check DNS and SSL along the way." },
    ],
    related: [
      { label: "VPS hosting", href: "/vps" },
      { label: "Docker hosting", href: "/docker-hosting" },
      { label: "Best VPS for WordPress", href: "/blog/best-vps-for-wordpress" },
      { label: "Pricing", href: "/pricing" },
      { label: "Free tools", href: "/tools" },
    ],
  };
}

export default async function WordPressVpsHostingPage() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const pricing = cheapestVpsPricing(plans);
  return <UseCaseLanding content={buildContent(pricing)} plans={plans} />;
}
