/* ============ first boot sequence ============ */
(function boot() {
  const bw = $('#bw'), items = $$('#bw-log li'); if (!bw) return; let run = 0;
  function play() { const id = ++run; bw.classList.remove('done'); items.forEach(li => li.className = '');
    if (RM) { items.forEach(li => li.className = 'ok'); bw.classList.add('done'); return; }
    items.forEach((li, i) => setTimeout(() => { if (id !== run) return; if (i) items[i - 1].className = 'ok'; li.className = 'run'; }, 300 + i * 650));
    setTimeout(() => { if (id !== run) return; items[items.length - 1].className = 'ok'; bw.classList.add('done'); }, 300 + items.length * 650); }
  $('#bw-re').addEventListener('click', play); let seen = false; watch(bw, v => { if (v && !seen) { seen = true; play(); } });
})();
watch($('#ust'), v => { if (v) $('#ust').classList.add('in'); }, { threshold: .3 });
/* ============ v2: chips after boot, compose services come up, stack toggles ============ */
(function v2() {
  const wrap = $('.mk-wrap'), bw = $('#bw');
