import "server-only";
import type { VpsPlan } from "./lib";

/**
 * Content of the use-case template's pages (tools/nxm/native/use-case).
 *
 * The words come from the LIVE page of the same route — app/(marketing)/<route>/
 * page.tsx (UseCaseLanding content: eyebrow/title/sub/intro/why/steps/specNote/
 * faq/related and metadata; /gaming-vps: GameLandingPage props) — laid into the
 * design's use-case sections (source/build_usecase.py + use_extra.py: hero +
 * mock + first-boot log + chips, "why" comparison, stack builder, features,
 * steps, plans, FAQ, "run something else", final). The comparison lists, the
 * first-boot/stack illustrations and the chips restate the live page's own
 * claims (and, for Nextcloud, what the catalogue's one-click image really
 * installs — OsTemplate.setupScript: Docker + the nextcloud container).
 *
 * Every plan name, price, spec, region and OS name is a function of `Ctx`,
 * which the loader builds from the system per request (fail closed). The live
 * pages hard-code several of these ("$32.99 Max", "1 vCPU, 2 GB RAM, 25 GB
 * NVMe", "Standard (4 GB)", "Singapore or Falkenstein, Germany", "Ubuntu
 * 24.04 or Debian 13"); here they are always the real values.
 */

export type Ctx = {
  plans: VpsPlan[];
  /** a plan by slug; throws when it isn't an active plan */
  plan: (slug: string) => VpsPlan;
  cheap: VpsPlan;
  top: VpsPlan;
  money: (dollars: number) => string;
  /** lowest real monthly price (intro rate when one applies) */
  from: string;
  /** regular price when `from` is an intro rate */
  renews: string | null;
  /** "from $8.99/mo" or "from $X/mo for your first term, then renews at $Y/mo" */
  fromPhrase: string;
  /** "Standard (4 GB)" */
  size: (slug: string) => string;
  /** "2 GB Starter" */
  gbName: (slug: string) => string;
  /** "1 vCPU, 2 GB RAM, 25 GB NVMe, 1 TB transfer" */
  spec: (slug: string) => string;
  /** "Singapore or Falkenstein, Germany" (city-level, enabled nodes) */
  regionsOr: string;
  /** "Singapore or Germany" (customer labels, enabled nodes) */
  countriesOr: string;
  regionCount: number;
  /** display name of an active OS image, e.g. "Ubuntu 24.04 LTS"; throws when missing */
  os: (slug: string) => string;
};

export type Feat = [icon: string, title: string, body: string];
export type StackOpt = [id: string, name: string, sub: string, on: boolean];
export type StackLayer = [id: string, name: string, sub: string, cls: string, icon: string, app: boolean];
export type LinkItem = { label: string; route: string; logo?: string };

export type UseCasePage = {
  kind: "app" | "vps";
  crumb: string;
  seo: { title: string; description: string };
  product: { name: string; description: string };
  /** accent (the design's --acc) and hero art (.us-art.art-<name>) */
  acc: string;
  art: "vps" | "web" | "cloud" | "matrix" | "code";
  app: string;
  /** mask-tinted brand mark class (lg-*) when the repo has the brand asset */
  logo?: string;
  /** Aurora icon for apps without a brand asset / the VPS pill */
  icon: string;
  kick?: string;
  cta: string;
  /** plan whose deploy link the hero/final CTAs use */
  deployPlan: string;
  h1a: string;
  h1b: string;
  sub: string;
  ok: [icon: string, text: string][];
  visual:
    | { kind: "mock"; mock: string; bootLabel: string; boot: string[]; chips: string[] }
    | { kind: "bill"; plan: string }
    | { kind: "games" };
  vst: string;
  vsl: string;
  vsa: string;
  vsai: string[];
  vsbi: string[];
  prose: string[];
  stack?: { lede: string; opts: StackOpt[]; layers: StackLayer[] };
  whyTitle: string;
  feats: Feat[];
  stepsTitle: string;
  steps: [title: string, body: string][];
  planTitle: string;
  planl: string;
  rec: string;
  recTag: string;
  /** show only these plans (slugs, in order), with a one-line blurb each */
  only?: { slug: string; blurb: string }[];
  guides?: { family?: string; label?: string; route: string }[];
  faqTitle: string;
  faq: [q: string, a: string][];
  moreTitle: string;
  more: LinkItem[];
  final: string;
};

// ── shared link lists ───────────────────────────────────────────────────────
/** The design's "Run something else?" list (build_usecase.py ALL), on the
 *  live routes (the design's /vpn-hosting is live /vpn-server-hosting). */
const APPS: (LinkItem & { key: string })[] = [
  { key: "wordpress", label: "WordPress", route: "/wordpress-vps-hosting", logo: "lg-wordpress" },
  { key: "docker", label: "Docker", route: "/docker-hosting", logo: "lg-docker" },
  { key: "n8n", label: "n8n", route: "/n8n-hosting" },
  { key: "nextcloud", label: "Nextcloud", route: "/nextcloud-hosting", logo: "lg-nextcloud" },
  { key: "nodejs", label: "Node.js", route: "/nodejs-hosting", logo: "lg-nodejs" },
  { key: "vpn", label: "VPN", route: "/vpn-server-hosting" },
  { key: "discord-bot", label: "Discord bots", route: "/discord-bot-hosting", logo: "lg-discord" },
  { key: "fivem", label: "FiveM", route: "/fivem-server-hosting" },
];
/** + the live page's own "Related" links that aren't app pages */
const appMore = (self: string, extra: LinkItem[] = []): LinkItem[] => [
  ...APPS.filter((a) => a.key !== self),
  { label: "VPS hosting", route: "/vps" },
  ...extra,
  { label: "Pricing", route: "/pricing" },
  { label: "Free tools", route: "/tools" },
];
const vpsMore = (self: string): LinkItem[] =>
  [
    { label: "Cheap VPS", route: "/cheap-vps-hosting" },
    { label: "Affordable VPS", route: "/affordable-vps-hosting" },
    { label: "Best value VPS", route: "/best-value-vps" },
    { label: "VPS hosting", route: "/vps" },
    { label: "Pricing", route: "/pricing" },
    { label: "Free tools", route: "/tools" },
  ].filter((l) => l.route !== self);

const n = (k: number) => ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"][k] ?? String(k);
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

// ── mocks (the design's .wp/.dk pattern, per app) ──────────────────────────
const n8nMock = `<div class="n8"><div class="n8-head"><span data-au-icon="pulse" data-grad></span>My workflow<span class="n8-tog">Active<i></i></span></div>
<div class="n8-cv"><div class="n8-flow"><div class="n8-node"><i class="tr"><span data-au-icon="bolt" data-grad></span></i><b>Webhook</b></div><span class="n8-w"></span><div class="n8-node"><i><span data-au-icon="globe" data-grad></span></i><b>HTTP Request</b></div><span class="n8-w"></span><div class="n8-node"><i><span data-au-icon="gear" data-grad></span></i><b>IF</b></div><span class="n8-w"></span><div class="n8-node"><i><span data-au-icon="database" data-grad></span></i><b>Postgres</b></div></div></div>
<div class="n8-log"><div>Webhook<em>1 item</em></div><div>HTTP Request<em>1 item</em></div><div>Postgres<em>1 row</em></div></div></div>`;

const nextcloudMock = `<div class="ncm"><div class="ncm-bar"><span class="lgm w lg-nextcloud"></span>Files<span>Search</span></div>
<div class="ncm-body"><div class="ncm-side"><div class="on"><i></i>All files</div><div><i></i>Recent</div><div><i></i>Favorites</div><div><i></i>Shared</div><div><i></i>Calendar</div><div><i></i>Contacts</div></div>
<div class="ncm-main"><div class="ncm-crumb">All files</div><div class="ncm-r"><i></i><b>Documents</b><span>Folder</span></div><div class="ncm-r"><i></i><b>Photos</b><span>Folder</span></div><div class="ncm-r"><i></i><b>Shared with family</b><span>Folder</span></div><div class="ncm-r"><i class="fl"></i><b>notes.md</b><span>File</span></div><div class="ncm-r"><i class="fl"></i><b>contract.pdf</b><span>File</span></div></div></div></div>`;

const nodeMock = `<div class="dk acc"><div class="dk-head"><span class="lgm lg-nodejs"></span>server.js</div><div class="dk-code"><span class="k">import</span> express <span class="k">from</span> <span class="s">"express"</span>;

<span class="k">const</span> app = express();
app.get(<span class="s">"/health"</span>, (req, res) =&gt;
  res.send(<span class="s">"ok"</span>));
app.listen(<span class="s">3000</span>);

<span class="c"># pm2 start server.js --name api</span></div>
<div class="dk-svc"><div class="dks"><i class="bx"></i><div><b>api</b><small>node server.js, port 3000</small></div><em>starting</em></div><div class="dks"><i class="bx"></i><div><b>worker</b><small>background jobs</small></div><em>starting</em></div><div class="dks"><i class="bx"></i><div><b>nginx</b><small>reverse proxy, port 443</small></div><em>starting</em></div></div></div>`;

const discordMock = `<div class="dc"><div class="dc-side"><i class="on"><span class="lgm w lg-discord"></span></i><i></i><i></i><i></i></div><div class="dc-main"><div class="dc-head"><s>#</s>general</div>
<div class="dc-msgs"><div class="dc-m"><i class="av"></i><div><b>alex</b><p><span class="cmd">/ping</span></p></div></div><div class="dc-m"><i class="av b"><span class="lgm w lg-discord"></span></i><div><b>YourBot<em>APP</em></b><p>Pong!</p></div></div><div class="dc-m"><i class="av u2"></i><div><b>sam</b><p><span class="cmd">/help</span></p></div></div><div class="dc-m"><i class="av b"><span class="lgm w lg-discord"></span></i><div><b>YourBot<em>APP</em></b><p>Here is everything I can do.</p></div></div></div>
<div class="dc-in">Message #general</div></div></div>`;

// ── pages ───────────────────────────────────────────────────────────────────
type Build = (c: Ctx) => UseCasePage;

/** live: app/(marketing)/n8n-hosting/page.tsx */
const n8n: Build = (c) => ({
  kind: "app", crumb: "n8n hosting",
  seo: {
    title: "n8n Hosting — Self-Hosted n8n VPS, One-Click, Full Root",
    description: `Self-host n8n on a fast NVMe VPS with a one-click install, full root, unlimited workflows, dedicated IPv4, daily backups, and DDoS protection. From ${c.from}/mo.`,
  },
  product: { name: "Nxeon n8n Hosting", description: "Own your automation: one-click n8n on an NVMe VPS with full root, dedicated IP, backups and DDoS protection. Unlimited workflows, your data." },
  acc: "#EA4B71", art: "matrix", app: "n8n", icon: "pulse", cta: "n8n", deployPlan: "starter",
  h1a: "Self-host n8n", h1b: "on a real VPS.",
  sub: `Run your own n8n automation server with a one-click install, full root, and no per-execution fees. Unlimited workflows on a dedicated NVMe box, ${c.fromPhrase}.`,
  ok: [["bolt", "Live in under a minute"], ["terminal", "Full root"], ["backup", "Daily backups"]],
  visual: {
    kind: "mock", mock: n8nMock, bootLabel: "first boot",
    boot: ["Provisioning NVMe server", "Assigning your dedicated IPv4", "Installing n8n", "Starting n8n", "n8n editor ready"],
    chips: ["n8n running", "No execution limits", "Daily backup scheduled"],
  },
  vst: "Why self-host n8n?",
  vsl: "n8n is at its best when you own it: no execution limits, no per-workflow pricing, and your data never leaves your server. Self-hosting it on a VPS gives you a dedicated machine with its own IP — the right home for workflows that touch private APIs, internal databases, and credentials you'd rather not hand to a SaaS.",
  vsa: "Typical hosted automation",
  vsai: ["Per-execution or per-workflow pricing", "Execution limits", "Credentials in someone else's multi-tenant cloud"],
  vsbi: ["No execution limits, no per-workflow fees", "Unlimited workflows on one flat server price", "Credentials and data stay on your server", "A dedicated IPv4 for webhooks and allow-lists"],
  prose: ["Nxeon deploys n8n for you in one click, running and reachable on first boot, so you skip the Node, database, and reverse-proxy setup and go straight to building automations. Everything runs on enterprise NVMe over a self-healing ZFS mirror, so busy schedules and webhook bursts stay responsive."],
  stack: {
    lede: "Because you have full root, you can put n8n behind your own domain and SSL, pin it to a version you trust, connect it to a Postgres database for durable execution history, and snapshot before every upgrade. It's your automation hub, on infrastructure you control.",
    opts: [["n8-ssl", "Your domain and SSL", "Editor and webhook URLs over HTTPS", true], ["n8-pg", "PostgreSQL", "Durable execution history", false]],
    layers: [["", "n8n", "your workflows", "app", "pulse", true], ["n8-ssl", "Domain and SSL", "HTTPS for editor and webhooks", "sl-o", "lock", false], ["n8-pg", "PostgreSQL", "execution history", "sl-o", "database", false],
      ["", "Full root", "SSH, env vars, versions", "", "terminal", false], ["", "NVMe on a ZFS mirror", "self-healing storage", "hw", "cpu", false]],
  },
  whyTitle: "Built for n8n",
  feats: [
    ["rocket", "One-click n8n install", "Choose the n8n image and your server boots with n8n installed and running — no Node, database, or proxy wrangling before your first workflow."],
    ["pulse", "No execution limits", "Self-hosted means no per-execution billing and no workflow caps. Run as many automations and steps as your server can handle."],
    ["lock", "Your data stays yours", "Credentials, payloads, and execution history live on your own VPS behind your firewall — not in someone else's multi-tenant cloud."],
    ["terminal", "Full root + dedicated IP", "SSH in to add a domain and SSL, set environment variables, or wire n8n to a Postgres database. A dedicated IPv4 makes webhooks and allow-lists reliable."],
    ["backup", "Snapshots before upgrades", "Take an instant snapshot before bumping n8n to a new version — if a node changes behaviour, roll back in seconds."],
    ["shield", "DDoS protection + backups", "Always-on DDoS mitigation, a managed firewall, and automatic daily backups keep your automation server online and recoverable."],
  ],
  stepsTitle: "Up and running in minutes",
  steps: [
    ["Create your account", "Sign up with no credit card required and open the deploy wizard."],
    ["Pick n8n + a plan", `Select the one-click n8n image and a plan (${c.plan("starter").n} is plenty to begin), then deploy — n8n is live in under a minute.`],
    ["Add a domain + SSL", "Point a domain at your dedicated IP and issue SSL so your editor and webhook URLs run over HTTPS."],
    ["Build your first workflow", "Open the n8n editor, connect your apps and credentials, and start automating. Full root is there whenever you want to tune it."],
  ],
  planTitle: "Pick your size",
  planl: `n8n runs comfortably on a ${c.gbName("starter")} for personal and small-team automation. Move up to ${c.size("standard")} if you run many concurrent workflows, heavy data transforms, or a bundled Postgres database — and resize any time without a rebuild.`,
  rec: "starter", recTag: "Best for n8n",
  faqTitle: "n8n hosting, answered",
  faq: [
    ["Is n8n really one-click here?", "Yes. Pick the one-click n8n image and your VPS boots with n8n installed and running. Point a domain at it, add SSL, and you're building workflows — no manual Node or database setup."],
    ["Do I pay per execution or per workflow?", "No. This is self-hosted n8n on your own VPS, so there are no per-execution fees and no workflow limits. You pay a flat monthly price for the server and run as much as it can handle."],
