      ["Why does CPU clock speed matter for game servers?", "Many game servers — Minecraft, FiveM, Rust, Palworld — are single-thread bound, meaning one fast core does most of the work. That's why a high per-core clock often matters more than a high core count, and why servers can lag even with lots of unused RAM."],
      ["Do I get DDoS protection?", "Yes. Every Nxeon VPS includes always-on volumetric DDoS mitigation at the network edge plus a managed firewall, so an attack aimed at a game server is absorbed before it reaches you."],
    ],
    moreTitle: "Related",
    more: [
      { label: "All game servers", route: "/game-servers" },
      { label: "VPS hosting", route: "/vps" },
      { label: "Discord bot hosting", route: "/discord-bot-hosting", logo: "lg-discord" },
      { label: "Minecraft server hosting", route: "/minecraft-server-hosting" },
      { label: "Pricing", route: "/pricing" },
    ],
    final: "Your game server, your rules.",
  };
};

export const PAGES: Record<string, Build> = {
  n8n, nextcloud, nodejs, "discord-bot": discordBot,
  "cheap-vps": cheapVps, "affordable-vps": affordableVps, "best-value-vps": bestValueVps, "gaming-vps": gamingVps,
};

