      { name: "Bangkok", cc: "th", lat: 13.76, lon: 100.5, anchor: "t" }, { name: "Hong Kong", cc: "hk", lat: 22.32, lon: 114.17, anchor: "t" },
      { name: "Manila", cc: "ph", lat: 14.6, lon: 120.98, anchor: "r" }, { name: "Mumbai", cc: "in", lat: 19.08, lon: 72.88, anchor: "t" },
