  fsn1: {
    area: "Central Europe", continent: "Europe", blurb: "Central Europe, data stays in the EU", tz: "Europe/Berlin", map: "eu", acc: "#9B8CFF",
    cities: [
      { name: "Prague", cc: "cz", lat: 50.08, lon: 14.44, anchor: "r" }, { name: "Berlin", cc: "de", lat: 52.52, lon: 13.4, anchor: "t" },
      { name: "Frankfurt", cc: "de", lat: 50.11, lon: 8.68, anchor: "l" }, { name: "Vienna", cc: "at", lat: 48.21, lon: 16.37, anchor: "b" },
      { name: "Amsterdam", cc: "nl", lat: 52.37, lon: 4.9, anchor: "t" }, { name: "Warsaw", cc: "pl", lat: 52.23, lon: 21.01, anchor: "r" },
