      { name: "Stockholm", cc: "se", lat: 59.33, lon: 18.07, anchor: "t" },
    ],
  },
};
/** The design's map crops (assets/maps/maps.json) — equirectangular bounds. */
export const MAPS = { apac: { W: 1600, H: 1468, lon: [64, 160], lat: [-46, 42] }, eu: { W: 1600, H: 1520, lon: [-14, 33], lat: [35, 64] } } as const;

