import "server-only";
import fs from "node:fs";
import path from "node:path";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { esc, introSpan, nxmHref, productLd, usd, vpsPlans, type NxmLoad, type VpsPlan } from "./lib";
import { btn, useCaseCards } from "./cards";
import { deployRegions, gameArt, gameName, gameRoute } from "./games-lib";
import { PAGES, type Ctx, type LinkItem, type UseCasePage } from "./use-case-content";

/**
 * Use-case template (tools/nxm/native/use-case — the design's source/pages/_use
 * page) for /n8n-hosting, /nextcloud-hosting, /nodejs-hosting,
 * /discord-bot-hosting, /cheap-vps-hosting, /affordable-vps-hosting,
 * /best-value-vps and /gaming-vps (tools/nxm/routes/use-case.json → p.page).
 *
 * Content: app/nxm/_data/use-case-content.ts (from each live page). Every
 * plan, price, spec, region and OS name is read here per request from the
 * same sources checkout uses (db.plan via vpsPlans, enabled db.node rows,
 * db.osTemplate, the dedicated-IP price setting); missing data throws.
 */

const d = (dollars: number) => usd(Math.round(dollars * 100));
const orList = (xs: string[]) => (xs.length <= 1 ? xs[0] ?? "" : `${xs.slice(0, -1).join(", ")} or ${xs[xs.length - 1]}`);
const uniq = <T,>(xs: T[]) => [...new Set(xs)];
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

async function context(): Promise<Ctx> {
  const [plans, regions, ipCents, images] = await Promise.all([
    vpsPlans(), deployRegions(), dedicatedIpMonthlyCents(),
    db.osTemplate.findMany({ where: { active: true }, select: { slug: true, name: true } }),
  ]);
  if (!plans.length) throw new Error("nxm use-case: no active VPS plans");
  if (!regions.length) throw new Error("nxm use-case: no enabled regions");
  // every one of these pages says a dedicated IPv4 is included in the price
  if (ipCents > 0) throw new Error(`nxm use-case: the copy says a dedicated IPv4 is included, but dedicated_ip_price_cents is ${ipCents}`);
  const bySlug = new Map(plans.map((p) => [p.slug, p]));
  const plan = (slug: string) => {
    const p = bySlug.get(slug);
    if (!p) throw new Error(`nxm use-case: no active VPS plan "${slug}"`);
    return p;
  };
  const cheap = plans.reduce((a, b) => (a.p <= b.p ? a : b));
  const top = plans.reduce((a, b) => (a.p >= b.p ? a : b));
  const from = d(cheap.i ?? cheap.p);
  const renews = cheap.i != null ? d(cheap.p) : null;
  const osName = new Map(images.map((i) => [i.slug, i.name]));
  const continents = regions.map((r) => {
    if (!r.info) throw new Error(`nxm use-case: no geography for region ${r.code}`);
    return r.info.continent;
  });
  return {
    plans, plan, cheap, top, money: d, from, renews,
    fromPhrase: renews ? `from ${from}/mo for your ${introSpan(cheap.it)}, then renews at ${renews}/mo` : `from ${from}/mo`,
    size: (s) => `${plan(s).n} (${plan(s).ram} GB)`,
    gbName: (s) => `${plan(s).ram} GB ${plan(s).n}`,
    spec: (s) => { const p = plan(s); return `${p.cpu} vCPU, ${p.ram} GB RAM, ${p.disk} GB NVMe, ${p.bw} TB transfer`; },
    regionsOr: orList(uniq(regions.map((r) => { const city = r.city.split(",")[0].trim(); return city === r.label ? r.label : `${city}, ${r.label}`; }))),
    countriesOr: orList(uniq(regions.map((r) => r.label))),
    continentsOr: orList(uniq(continents)),
    regionCount: regions.length,
    os: (slug) => {
      const name = osName.get(slug);
      if (!name) throw new Error(`nxm use-case: no active OS image "${slug}"`);
      return name;
    },
  };
}

function pick(p: Record<string, string>) {
  const build = PAGES[p.page];
  if (!build) notFound();
  return build;
}

// ── links: a route already on the new site stays inside it while staged ────
const ported = new Map<string, boolean>();
function href(route: string) {
  if (!ported.has(route)) ported.set(route, fs.existsSync(path.join(process.cwd(), "app/nxm", route, "page.tsx")));
  return ported.get(route) ? nxmHref(route) : route;
}

// ── markup (the design's use-case template pieces, build_usecase.py/use_extra.py) ──
const icon = (n: string, grad = false) => `<span data-au-icon="${esc(n)}"${grad ? " data-grad" : ""}></span>`;
const mark = (cls: string, label?: string) =>
  `<span class="lgm ${esc(cls)}"${label ? ` role="img" aria-label="${esc(label)}"` : ' aria-hidden="true"'}></span>`;

function lead(u: UseCasePage) {
  if (u.kind === "vps") return `<p class="h2pill">${icon(u.icon, true)}${esc(u.kick ?? u.app)}</p>`;
  const logo = u.logo ? mark(u.logo, u.app) : icon(u.icon, true);
  return `<div class="lk"><span class="lk-app${u.logo ? "" : " ic"}">${logo}</span><span class="lk-x">×</span><span class="lk-nx"><span data-au-logo="play" data-w="34"></span></span><span class="lk-t">${esc(u.app)} on Nxeon</span></div>`;
}

/** Real price for a plan card / the bill: the intro rate when one applies. */
const monthly = (p: VpsPlan) => d(p.i ?? p.p);
const billNote = (p: VpsPlan) => (p.i != null ? `${cap(introSpan(p.it))}, then ${d(p.p)} a month` : "All-in, billed monthly");
const specLine = (p: VpsPlan) => `${p.cpu} vCPU, ${p.ram} GB RAM, ${p.disk} GB NVMe, ${p.bw} TB transfer`;
/** The rows the live VPS pages say every plan includes (cheap-vps-hosting intro). */
const INCLUDED = ["Dedicated IPv4", "DDoS protection", "Managed firewall", "Daily backups", "Instant snapshots"];

function visual(u: UseCasePage, c: Ctx, games: GameCard[]) {
  const v = u.visual;
  if (v.kind === "mock") {
    const boot = v.boot.map((b) => `<li>${esc(b)}</li>`).join("");
    const chips = v.chips.map((t, k) => `<span class="mkc c${k + 1}"><i></i>${esc(t)}</span>`).join("");
    return `<div class="mk-wrap">${v.mock}<div class="bw au-glass" id="bw" aria-label="${esc(v.bootLabel)}"><div class="bw-top"><span>${esc(v.bootLabel)}</span><button type="button" class="bw-re" id="bw-re" aria-label="Replay">${icon("refresh")}</button></div><ol class="bw-log" id="bw-log">${boot}</ol></div>${chips}</div>`;
  }
  if (v.kind === "bill") {
    const sel = c.plan(v.plan);
    const seg = c.plans.map((p) => `<button type="button" data-v="${esc(p.slug)}" data-n="${esc(p.n)}" data-s="${esc(specLine(p))}" data-p="${esc(monthly(p))}" data-note="${esc(billNote(p))}" aria-pressed="${p.slug === sel.slug}">${esc(p.n)}</button>`).join("");
    const rows = INCLUDED.map((x) => `<li><span>${esc(x)}</span><em>Included</em></li>`).join("");
    return `<div class="rc-wrap"><div class="rc au-glass"><div class="rc-top"><span>Your monthly bill</span><div class="au-seg" id="rc-seg" role="group" aria-label="Plan">${seg}</div></div>`
      + `<ul class="rc-rows"><li class="rc-srv"><span><b id="rc-n">${esc(sel.n)}</b><small id="rc-s">${esc(specLine(sel))}</small></span><b id="rc-p">${esc(monthly(sel))}</b></li>${rows}</ul>`
      + `<div class="rc-tot"><span>Total per month</span><b id="rc-t">${esc(monthly(sel))}</b></div><p class="rc-note" id="rc-note">${esc(billNote(sel))}</p></div></div>`;
  }
  const tiles = games.filter((g) => g.art).slice(0, 5)
    .map((g) => `<a class="gv-c" href="${esc(g.href)}" style="background-image:url('${esc(g.art!)}')"><b>${esc(g.name)}</b></a>`).join("");
  return `<div class="gv"><div class="gv-grid">${tiles}<div class="gv-c any">${mark("lg-steam")}<b>Any game with a dedicated server</b></div></div>`
    + `<div class="bw au-glass gv-t" aria-label="Example SSH session"><div class="bw-top"><span>root@your-vps: ~</span></div><pre><i>$</i> steamcmd +login anonymous \\\n    +app_update &lt;app id&gt; validate +quit</pre></div></div>`;
}

type GameCard = { name: string; label: string; href: string; art: string | null };
function gameCards(u: UseCasePage): GameCard[] {
  return (u.guides ?? []).map((g) => {
    if (!g.family) return { name: g.label ?? g.route, label: g.label ?? g.route, href: href(g.route), art: null };
    const route = gameRoute(g.family);
    if (!route) throw new Error(`nxm use-case: no route for game family ${g.family}`);
    const name = gameName(g.family);
    return { name, label: `${name} server hosting`, href: href(route), art: gameArt(g.family).cover };
  });
}

function stack(u: UseCasePage) {
  if (!u.stack) return "";
  const opts = u.stack.opts.map(([id, name, sub, on]) =>
    `<label class="au-toggle"><input type="checkbox" data-layer="${esc(id)}"${on ? " checked" : ""}><span class="tr"><span class="kn"></span></span><span>${esc(name)}<small>${esc(sub)}</small></span></label>`).join("");
  const layers = u.stack.layers.map(([id, name, sub, cls, ic, app]) => {
    const lead = app ? (u.logo ? mark(u.logo) : icon(ic, true)) : icon(ic, true);
    return `<div class="sl ${esc(cls)}"${id ? ` id="${esc(id)}"` : ""}>${lead}<b>${esc(name)}</b><small>${esc(sub)}</small></div>`;
  }).join("");
  return `<section class="section" id="stack" aria-labelledby="sk-title" style="padding-top:0"><div class="container sk"><div><h2 class="h2" id="sk-title">Build your ${esc(u.app)} stack</h2><p class="lede">${esc(u.stack.lede)}</p><div class="sk-opts">${opts}</div></div><div class="sk-vis" id="sk-vis" aria-hidden="true">${layers}</div></div></section>`;
}

/** The design's .upl plan cards (cards.ts useCaseCards markup) for a chosen
 *  subset of plans, each with its one-line fit from the live page. */
function someCards(c: Ctx, only: NonNullable<UseCasePage["only"]>, rec: string, tag: string) {
  return `<div class="upl u3">${only.map(({ slug, blurb }) => {
    const p = c.plan(slug), isRec = p.slug === rec;
    const price = p.i != null
      ? `<p class="pp"><b>${d(p.i)}</b><s>${d(p.p)}</s></p><p class="then">${cap(introSpan(p.it))}, then ${d(p.p)} a month</p>`
      : `<p class="pp"><b>${d(p.p)}</b></p><p class="then">a month</p>`;
    return `<article class="au-card up${isRec ? " rec" : ""}">${isRec ? `<span class="tag">${esc(tag)}</span>` : ""}<h3>${esc(p.n)}</h3>${price}<p class="gf">${esc(blurb)}</p><ul><li>CPU<b>${p.cpu} vCPU</b></li><li>Memory<b>${p.ram} GB</b></li><li>NVMe<b>${p.disk} GB</b></li><li>Bandwidth<b>${p.bw} TB</b></li></ul>${btn(isRec, p.href, `Deploy ${p.n}`)}</article>`;
  }).join("")}</div>`;
}

function guides(cards: GameCard[]) {
  if (!cards.length) return "";
  const items = cards.map((g) => `<a class="au-card au-hov ug" href="${esc(g.href)}">${g.art ? `<span class="ug-art" style="background-image:url('${esc(g.art)}')"></span>` : `<span class="ug-art any">${icon("game", true)}</span>`}<b>${esc(g.label)}</b></a>`).join("");
  return `<section class="section" id="guides" aria-labelledby="gd-title" style="padding-top:0"><div class="container"><div class="gp-head"><div><h2 class="h2" id="gd-title">Step-by-step setup guides</h2></div></div><div class="ugd">${items}</div></div></section>`;
}

const moreLinks = (items: LinkItem[]) => items.map((l) => `<a href="${esc(href(l.route))}">${l.logo ? mark(l.logo) : ""}${esc(l.label)}</a>`).join("");

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const build = pick(p);
  const c = await context();
  const u = build(c);
  const games = gameCards(u);
  const shown = u.only ? u.only.map((o) => c.plan(o.slug)) : c.plans;
  c.plan(u.rec);
  return {
    slots: {
      acc: u.acc, art: u.art, "lead:html": lead(u),
      h1a: u.h1a, h1b: u.h1b, sub: u.sub, deploy: c.plan(u.deployPlan).href, cta: u.cta,
      "ok:html": u.ok.map(([i, t]) => `<li>${icon(i, true)}${esc(t)}</li>`).join(""),
      "visual:html": visual(u, c, games),
      vst: u.vst, vsl: u.vsl, vsa: u.vsa,
      "vsai:html": u.vsai.map((x) => `<li>${esc(x)}</li>`).join(""),
      "vsbi:html": u.vsbi.map((x) => `<li>${esc(x)}</li>`).join(""),
      "prose:html": u.prose.length ? `<div class="us-prose">${u.prose.map((x) => `<p>${esc(x)}</p>`).join("")}</div>` : "",
      "stack:html": stack(u),
      whytitle: u.whyTitle,
      "feats:html": u.feats.map(([ic, h, b]) => `<article class="au-card au-hov"><span class="au-tile">${icon(ic)}</span><h3>${esc(h)}</h3><p>${esc(b)}</p></article>`).join(""),
      stepstitle: u.stepsTitle,
      "steps:html": u.steps.map(([h, b], k) => `<li><b>${k + 1}</b><h3>${esc(h)}</h3><p>${esc(b)}</p></li>`).join(""),
      plantitle: u.planTitle, planl: u.planl,
      "plans:html": u.only ? someCards(c, u.only, u.rec, u.recTag) : useCaseCards(c.plans, u.rec, u.recTag),
      "guides:html": guides(games),
      faqtitle: u.faqTitle,
      "faq:html": u.faq.map(([q, a], k) => `<details${k === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join(""),
      moretitle: u.moreTitle, "more:html": moreLinks(u.more), final: u.final,
    },
    crumb: u.crumb,
    jsonLd: [productLd(u.product.name, u.product.description, routeOf(p.page), shown.map((x) => ({ name: `${x.n} VPS`, price: x.i ?? x.p })))],
  };
}

const ROUTE_OF: Record<string, string> = {
  n8n: "/n8n-hosting", nextcloud: "/nextcloud-hosting", nodejs: "/nodejs-hosting", "discord-bot": "/discord-bot-hosting",
  "cheap-vps": "/cheap-vps-hosting", "affordable-vps": "/affordable-vps-hosting", "best-value-vps": "/best-value-vps", "gaming-vps": "/gaming-vps",
};
const routeOf = (page: string) => ROUTE_OF[page] ?? notFound();

export async function meta(p: Record<string, string>) {
  const build = pick(p);
  const u = build(await context());
  return { title: u.seo.title, description: u.seo.description, crumb: u.crumb };
}

